class Order private constructor(
    val id: OrderId,
    val customer: CustomerId,
    val lines: List<Line>,
    val status: Status,
) {
    companion object {
        fun open(customer: CustomerId, lines: List<Line>): Order {
            require(lines.isNotEmpty()) { "cannot open an empty order" }
            return Order(OrderId.new(), customer, lines.toList(), Status.DRAFT)
        }
    }
}
